// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/health", wrapper.GetHealth)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/register", wrapper.Register)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/login", wrapper.Login)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/refresh", wrapper.RefreshToken)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/auth/logout", wrapper.Logout)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/cards", wrapper.ListCards)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/cards/{cardId}", wrapper.GetCard)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/banlist", wrapper.GetBanlist)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/archetypes", wrapper.ListArchetypes)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/sets", wrapper.ListSets)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/decks", wrapper.ListDecks)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/decks", wrapper.CreateDeck)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/decks/import", wrapper.ImportDeck)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/decks/{deckId}", wrapper.DeleteDeck)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/decks/{deckId}", wrapper.GetDeck)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/decks/{deckId}", wrapper.UpdateDeck)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/decks/{deckId}/copy", wrapper.CopyDeck)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/decks/{deckId}/export", wrapper.ExportDeck)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/decks/{deckId}/like", wrapper.UnlikeDeck)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/decks/{deckId}/like", wrapper.LikeDeck)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/decks/{deckId}/comments", wrapper.ListDeckComments)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/decks/{deckId}/comments", wrapper.CreateDeckComment)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/me", wrapper.GetMe)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/me", wrapper.UpdateMe)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/me/decks", wrapper.ListMyDecks)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/me/collection", wrapper.GetMyCollection)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/me/collection", wrapper.ReplaceMyCollection)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/users/{username}", wrapper.GetUser)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/users/{username}/decks", wrapper.ListUserDecks)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/users/{username}/follow", wrapper.UnfollowUser)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/users/{username}/follow", wrapper.FollowUser)

	return m
}

