// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListArchetypes Lista arquétipos presentes na era
	// (GET /archetypes)
	ListArchetypes(ctx context.Context, request ListArchetypesRequestObject) (ListArchetypesResponseObject, error)
	// Login Autentica com e-mail e senha
	// (POST /auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Logout Revoga o refresh token informado
	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// RefreshToken Troca um refresh token por um novo par de tokens
	// (POST /auth/refresh)
	RefreshToken(ctx context.Context, request RefreshTokenRequestObject) (RefreshTokenResponseObject, error)
	// Register Cria uma conta
	// (POST /auth/register)
	Register(ctx context.Context, request RegisterRequestObject) (RegisterResponseObject, error)
	// GetBanlist Lista de cartas proibidas, limitadas e semilimitadas da era
	// (GET /banlist)
	GetBanlist(ctx context.Context, request GetBanlistRequestObject) (GetBanlistResponseObject, error)
	// ListCards Busca cartas com filtros
	// (GET /cards)
	ListCards(ctx context.Context, request ListCardsRequestObject) (ListCardsResponseObject, error)
	// GetCard Detalha uma carta
	// (GET /cards/{cardId})
	GetCard(ctx context.Context, request GetCardRequestObject) (GetCardResponseObject, error)
	// ListDecks Marketplace de decks públicos
	// (GET /decks)
	ListDecks(ctx context.Context, request ListDecksRequestObject) (ListDecksResponseObject, error)
	// CreateDeck Cria um deck
	// (POST /decks)
	CreateDeck(ctx context.Context, request CreateDeckRequestObject) (CreateDeckResponseObject, error)
	// ImportDeck Importa um deck no formato YDK
	// (POST /decks/import)
	ImportDeck(ctx context.Context, request ImportDeckRequestObject) (ImportDeckResponseObject, error)
	// DeleteDeck Remove um deck
	// (DELETE /decks/{deckId})
	DeleteDeck(ctx context.Context, request DeleteDeckRequestObject) (DeleteDeckResponseObject, error)
	// GetDeck Detalha um deck
	// (GET /decks/{deckId})
	GetDeck(ctx context.Context, request GetDeckRequestObject) (GetDeckResponseObject, error)
	// UpdateDeck Substitui o conteúdo de um deck
	// (PUT /decks/{deckId})
	UpdateDeck(ctx context.Context, request UpdateDeckRequestObject) (UpdateDeckResponseObject, error)
	// ListDeckComments Lista comentários de um deck
	// (GET /decks/{deckId}/comments)
	ListDeckComments(ctx context.Context, request ListDeckCommentsRequestObject) (ListDeckCommentsResponseObject, error)
	// CreateDeckComment Comenta em um deck
	// (POST /decks/{deckId}/comments)
	CreateDeckComment(ctx context.Context, request CreateDeckCommentRequestObject) (CreateDeckCommentResponseObject, error)
	// CopyDeck Copia um deck público para a conta do usuário
	// (POST /decks/{deckId}/copy)
	CopyDeck(ctx context.Context, request CopyDeckRequestObject) (CopyDeckResponseObject, error)
	// ExportDeck Exporta um deck no formato YDK
	// (GET /decks/{deckId}/export)
	ExportDeck(ctx context.Context, request ExportDeckRequestObject) (ExportDeckResponseObject, error)
	// UnlikeDeck Remove a curtida de um deck
	// (DELETE /decks/{deckId}/like)
	UnlikeDeck(ctx context.Context, request UnlikeDeckRequestObject) (UnlikeDeckResponseObject, error)
	// LikeDeck Curte um deck
	// (PUT /decks/{deckId}/like)
	LikeDeck(ctx context.Context, request LikeDeckRequestObject) (LikeDeckResponseObject, error)
	// GetHealth Verifica se o serviço está de pé
	// (GET /health)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// GetMe Retorna o perfil do usuário autenticado
	// (GET /me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// UpdateMe Atualiza o perfil do usuário autenticado
	// (PATCH /me)
	UpdateMe(ctx context.Context, request UpdateMeRequestObject) (UpdateMeResponseObject, error)
	// GetMyCollection Retorna a coleção do usuário
	// (GET /me/collection)
	GetMyCollection(ctx context.Context, request GetMyCollectionRequestObject) (GetMyCollectionResponseObject, error)
	// ReplaceMyCollection Substitui a coleção do usuário
	// (PUT /me/collection)
	ReplaceMyCollection(ctx context.Context, request ReplaceMyCollectionRequestObject) (ReplaceMyCollectionResponseObject, error)
	// ListMyDecks Lista os decks do usuário autenticado (inclui privados)
	// (GET /me/decks)
	ListMyDecks(ctx context.Context, request ListMyDecksRequestObject) (ListMyDecksResponseObject, error)
	// ListSets Lista sets lançados na era
	// (GET /sets)
	ListSets(ctx context.Context, request ListSetsRequestObject) (ListSetsResponseObject, error)
	// GetUser Perfil público de um usuário
	// (GET /users/{username})
	GetUser(ctx context.Context, request GetUserRequestObject) (GetUserResponseObject, error)
	// ListUserDecks Decks públicos de um usuário
	// (GET /users/{username}/decks)
	ListUserDecks(ctx context.Context, request ListUserDecksRequestObject) (ListUserDecksResponseObject, error)
	// UnfollowUser Deixa de seguir um usuário
	// (DELETE /users/{username}/follow)
	UnfollowUser(ctx context.Context, request UnfollowUserRequestObject) (UnfollowUserResponseObject, error)
	// FollowUser Segue um usuário
	// (PUT /users/{username}/follow)
	FollowUser(ctx context.Context, request FollowUserRequestObject) (FollowUserResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// ListArchetypes operation middleware
func (sh *strictHandler) ListArchetypes(w http.ResponseWriter, r *http.Request) {
	var request ListArchetypesRequestObject

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.ListArchetypes(ctx, request.(ListArchetypesRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "ListArchetypes")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(ListArchetypesResponseObject); ok {
		if err := validResponse.VisitListArchetypesResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

// Login operation middleware
func (sh *strictHandler) Login(w http.ResponseWriter, r *http.Request) {
	var request LoginRequestObject

	var body LoginJSONRequestBody
	if err := runtime.BindJSONBody(r, &body); err != nil {
		sh.options.RequestErrorHandlerFunc(w, r, fmt.Errorf("can't decode JSON body: %w", err))
		return
	}
	request.Body = &body

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.Login(ctx, request.(LoginRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "Login")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(LoginResponseObject); ok {
		if err := validResponse.VisitLoginResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

